<html lang="en">
<head>
<meta charset="utf-8">
<style>
  body { margin: 0; padding: var(--cc-space-l); box-sizing: border-box; font-family: var(--cc-font-family); }
  *, *::before, *::after { box-sizing: border-box; }

  .hero {
    position: relative;
    width: 100%;
    height: 168px;
    border-radius: var(--cc-radius);
    overflow: hidden;
    display: flex;
    align-items: center;
    gap: var(--cc-space-xl);
    padding: 0 var(--cc-space-xl);
    color: #FFFFFF;
    background: linear-gradient(115deg, #1B1464 0%, #6E5BD6 35%, #00BFB3 65%, #6E5BD6 85%, #1B1464 100%);
    background-size: 300% 300%;
    background-position: 0% 50%;
    animation: gradientShift 12s var(--cc-ease) 1 forwards;
  }
  @keyframes gradientShift {
    0% { background-position: 0% 50%; }
    100% { background-position: 100% 50%; }
  }

  .grid {
    position: absolute;
    inset: -40px;
    pointer-events: none;
    opacity: 0.14;
    background-image:
      linear-gradient(rgba(255,255,255,0.6) 1px, transparent 1px),
      linear-gradient(90deg, rgba(255,255,255,0.6) 1px, transparent 1px);
    background-size: 40px 40px;
    animation: gridDrift 12s linear 1 forwards;
  }
  @keyframes gridDrift {
    0% { transform: translate(0, 0); }
    100% { transform: translate(40px, 40px); }
  }
  .circuit { position: absolute; inset: 0; pointer-events: none; opacity: 0.18; }

  .art { position: relative; flex: 0 0 auto; width: 128px; height: 128px; z-index: 1; }
  .halo {
    position: absolute; inset: 14px; border-radius: 50%;
    background: radial-gradient(circle, rgba(255,255,255,0.45) 0%, rgba(0,191,179,0.25) 45%, transparent 72%);
    animation: haloPulse var(--cc-motion-slow) var(--cc-ease) 6 alternate;
  }
  @keyframes haloPulse {
    from { opacity: 0.6; transform: scale(0.92); }
    to { opacity: 1; transform: scale(1.06); }
  }
  .shield { position: absolute; inset: 16px; width: 96px; height: 96px; }
  .orbit {
    position: absolute; inset: 0;
    animation: spin 8s linear 2;
  }
  .orbit span {
    position: absolute; width: 8px; height: 8px; border-radius: 50%;
    background: #FFFFFF; box-shadow: 0 0 8px rgba(255,255,255,0.9);
  }
  .orbit span:nth-child(1) { top: 0; left: 60px; }
  .orbit span:nth-child(2) { bottom: 14px; left: 8px; opacity: 0.8; }
  .orbit span:nth-child(3) { bottom: 14px; right: 8px; opacity: 0.6; }
  @keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }

  .text { position: relative; z-index: 1; flex: 1 1 auto; min-width: 0; animation: fadeUp 0.6s var(--cc-ease) both; }
  @keyframes fadeUp {
    from { opacity: 0; transform: translateY(8px); }
    to { opacity: 1; transform: translateY(0); }
  }
  h1 { margin: 0; font-size: 1.75rem; font-weight: 600; line-height: 1.2; letter-spacing: -0.01em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .sub { margin: var(--cc-space-xs) 0 0; font-size: 0.875rem; opacity: 0.88; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }

  .chips { display: flex; flex-wrap: wrap; gap: var(--cc-space-s); margin-top: var(--cc-space-m); max-height: 64px; overflow: hidden; }
  .chip {
    display: inline-flex; align-items: center; gap: var(--cc-space-xs);
    padding: var(--cc-space-xs) var(--cc-space-s);
    border-radius: var(--cc-radius-s);
    font-size: 0.75rem; white-space: nowrap;
    background: rgba(255,255,255,0.14);
    border: 1px solid rgba(255,255,255,0.28);
    backdrop-filter: blur(6px);
  }
  .chip b { font-weight: 600; }
  .chip svg { width: 14px; height: 14px; flex: 0 0 auto; }

  .live {
    position: relative; z-index: 1; align-self: flex-start; margin-top: var(--cc-space-l);
    flex: 0 0 auto;
    display: inline-flex; align-items: center; gap: var(--cc-space-s);
    padding: var(--cc-space-xs) var(--cc-space-m);
    border-radius: var(--cc-radius-s);
    background: rgba(10,8,40,0.45);
    border: 1px solid rgba(255,255,255,0.3);
    font-size: 0.75rem; font-weight: 600; letter-spacing: 0.08em;
    animation: fadeUp 0.6s var(--cc-ease) both;
  }
  .dot { position: relative; width: 8px; height: 8px; border-radius: 50%; background: #3DDC84; }
  .dot::after {
    content: ""; position: absolute; inset: 0; border-radius: 50%;
    border: 2px solid #3DDC84;
    animation: ring var(--cc-motion-slow) var(--cc-ease) 8;
  }
  @keyframes ring {
    from { opacity: 0.9; transform: scale(1); }
    to { opacity: 0; transform: scale(2.6); }
  }

  @media (max-width: 640px) {
    .art { display: none; }
    h1 { font-size: 1.5rem; }
  }

  @media (prefers-reduced-motion: reduce) {
    *, *::before, *::after { animation: none !important; transition: none !important; }
  }
</style>
</head>
