    {% assign reasons = row["output_reasons"].value %}
    {% assign hasPii = false %}{% assign hasLeak = false %}{% assign hasMarkup = false %}{% assign hasOther = false %}
    {% assign firstCls = "" %}
    {% for r in reasons %}
      {% if r == "pii_in_response" %}{% assign hasPii = true %}{% assign c = "c-pii" %}
      {% elsif r == "system_prompt_leak" %}{% assign hasLeak = true %}{% assign c = "c-leak" %}
      {% elsif r == "unsafe_markup" %}{% assign hasMarkup = true %}{% assign c = "c-markup" %}
      {% else %}{% assign hasOther = true %}{% assign c = "c-other" %}{% endif %}
      {% if firstCls == "" %}{% assign firstCls = c %}{% endif %}
