    {% if hasPii %}{% assign stripeCls = "c-pii" %}{% elsif hasLeak %}{% assign stripeCls = "c-leak" %}{% elsif hasMarkup %}{% assign stripeCls = "c-markup" %}{% else %}{% assign stripeCls = "c-other" %}{% endif %}
