      <summary>
        <span class="stripe {{ stripeCls }}"></span>
        <div class="time">
          <span class="t-rel">{% if diff < 0 %}{{ row["@timestamp"].value | date: "%H:%M:%S" }}{% elsif diff < 60 %}{{ diff }}s ago{% elsif diff < 3600 %}{{ diff | divided_by: 60 | floor }}m ago{% elsif diff < 86400 %}{{ diff | divided_by: 3600 | floor }}h ago{% else %}{{ diff | divided_by: 86400 | floor }}d ago{% endif %}</span>
          <span class="t-abs">{{ row["@timestamp"].value | date: "%b %d, %H:%M:%S" }}</span>
        </div>
        <div class="badges">
          {% if hasPii %}
          <span class="badge c-pii"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 10a2 2 0 0 0-2 2c0 1.02-.1 2.51-.26 4"/><path d="M14 13.12c0 2.38 0 6.38-1 8.88"/><path d="M17.29 21.02c.12-.6.43-2.3.5-3.02"/><path d="M2 12a10 10 0 0 1 18-6"/><path d="M2 16h.01"/><path d="M21.8 16c.2-2 .131-5.354 0-6"/><path d="M5 19.5C5.5 18 6 15 6 12a6 6 0 0 1 .34-2"/><path d="M8.65 22c.21-.66.45-1.32.57-2"/><path d="M9 6.8a6 6 0 0 1 9 5.2v2"/></svg>pii_in_response</span>
          {% endif %}
          {% if hasLeak %}
          <span class="badge c-leak"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M2.586 17.414A2 2 0 0 0 2 18.828V21a1 1 0 0 0 1 1h3a1 1 0 0 0 1-1v-1a1 1 0 0 1 1-1h1a1 1 0 0 0 1-1v-1a1 1 0 0 1 1-1h.172a2 2 0 0 0 1.414-.586l.814-.814a6.5 6.5 0 1 0-4-4z"/><circle cx="16.5" cy="7.5" r=".5" fill="currentColor"/></svg>system_prompt_leak</span>
          {% endif %}
          {% if hasMarkup %}
          <span class="badge c-markup"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m18 16 4-4-4-4"/><path d="m6 8-4 4 4 4"/><path d="m14.5 4-5 16"/></svg>unsafe_markup</span>
          {% endif %}
          {% if hasOther %}
          {% for r in reasons %}{% unless r == "pii_in_response" or r == "system_prompt_leak" or r == "unsafe_markup" %}
          <span class="badge c-other"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3"/><path d="M12 9v4"/><path d="M12 17h.01"/></svg>{{ r }}</span>
          {% endunless %}{% endfor %}
          {% endif %}
        </div>
        <div class="meta">
          <span class="chip">{{ row["quality.persona"].value | default: "—" }}</span>
          <span class="chip">{{ row["quality.model"].value | default: "—" }}</span>
        </div>
        <span class="preview">{{ row["quality.prompt_text"].value }}</span>
        <svg class="chev" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m9 18 6-6-6-6"/></svg>
      </summary>

      <div class="body">
        <div>
          <div class="blk-lbl"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M19 21v-2a4 4 0 0 0-4-4H9a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>Prompt</div>
          <div class="bubble">{{ row["quality.prompt_text"].value | default: "—" }}</div>
        </div>

        <div>
          <div class="blk-lbl"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M12 8V4H8"/><rect width="16" height="12" x="4" y="8" rx="2"/><path d="M2 14h2"/><path d="M20 14h2"/><path d="M15 13v2"/><path d="M9 13v2"/></svg>Response</div>
          <div class="bubble resp {{ firstCls }}">{{ row["quality.response_text"].value | default: "—" }}</div>
        </div>

        <div class="callout {{ firstCls }}">
          <div class="blk-lbl"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 13c0 5-3.5 7.5-7.66 8.95a1 1 0 0 1-.67-.01C7.5 20.5 4 18 4 13V6a1 1 0 0 1 1-1c2 0 4.5-1.2 6.24-2.72a1.17 1.17 0 0 1 1.52 0C14.51 3.81 17 5 19 5a1 1 0 0 1 1 1z"/><path d="M12 8v4"/><path d="M12 16h.01"/></svg>Why it was flagged</div>
          <ul class="why">
            {% for r in reasons %}
            {% if r == "pii_in_response" %}
            <li>Sensitive data disclosed (OWASP LLM02)
              {% if row["quality.pii_types"].value %}
              <div class="pii-row">PII types:{% for p in row["quality.pii_types"].value %}<span class="pii">{{ p }}</span>{% endfor %}</div>
              {% endif %}
            </li>
            {% elsif r == "system_prompt_leak" %}
            <li>System prompt canary token found in the response (OWASP LLM07)</li>
            {% elsif r == "unsafe_markup" %}
            <li>Response contains unsafe markup such as script or HTML that could execute downstream (OWASP LLM05)</li>
            {% else %}
            <li>{{ r }}</li>
            {% endif %}
            {% endfor %}
          </ul>
          {% assign hidden = row["quality.hidden_count"].value | plus: 0 %}
          {% if row["quality.judge_reason"].value or hidden > 0 %}
          <div class="signals">
            {% if row["quality.judge_reason"].value %}
            <div class="sig"><span><b>Judge:</b> {{ row["quality.judge_reason"].value }}</span>{% if row["quality.faithfulness"].value != nil %}<span class="chip{% if row["quality.low_faithfulness"].value == true %} bad{% endif %}">Faithfulness {{ row["quality.faithfulness"].value }}/5</span>{% endif %}</div>
            {% endif %}
            {% if hidden > 0 %}
            <div class="sig"><span><b>Restricted docs matched:</b> {{ hidden }}</span></div>
            {% endif %}
          </div>
          {% endif %}
        </div>

        {% if row["trace.id"].value %}
