          <span class="trace-link"><a href="/app/discover#/?_a=(query:(language:kuery,query:'trace.id:%22{{ row["trace.id"].value }}%22'))">View trace<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M15 3h6v6"/><path d="M10 14 21 3"/><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h3"/></svg></a></span>
        </div>
        {% endif %}
      </div>
    </details>
    {% endfor %}
  </div>
  {% endif %}
</div>"},"panelIndex":"threat-feed","gridData":{"w":32,"x":0,"h":24,"y":0,"i":"threat-feed","sectionId":"live-activity"}},{"type":"custom_content","embeddableConfig":{"esql_query":["FROM traces-generic.otel-default
| WHERE service.name == "glassbox-backend"
