  .m-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
  .m-val { font-weight: 600; flex: none; }
  .bar-bg { height: 4px; background: var(--cc-color-border); border-radius: var(--cc-radius-s); overflow: hidden; }
  .bar { height: 100%; border-radius: var(--cc-radius-s); transform-origin: left center; animation: grow 1.2s var(--cc-ease) both; }
  .c0 { background: var(--cc-vis-1); }
  .c1 { background: var(--cc-vis-0); }
  .c2 { background: var(--cc-vis-3); }
  .empty { font-size: 0.875rem; opacity: 0.7; padding: var(--cc-space-l); text-align: center; }
  @keyframes draw { from { stroke-dashoffset: 100; } to { stroke-dashoffset: var(--off); } }
  @keyframes pulse { 0%, 100% { opacity: 0; } 50% { opacity: 0.7; } }
  @keyframes grow { from { transform: scaleX(0); } to { transform: scaleX(1); } }
  @media (prefers-reduced-motion: reduce) {
    .arc, .bar, .lvl-red .glow { animation: none; }
  }
</style>
<div class="card">
  <div class="hdr">
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="10"/><path d="M16 8h-6a2 2 0 1 0 0 4h4a2 2 0 1 1 0 4H8"/><path d="M12 18V6"/></svg>
    <span>Spend vs budget</span>
    <span class="sub">glassbox-backend · LLM10 unbounded consumption</span>
  </div>
  {% if rows.size == 0 %}
  <div class="empty">No GenAI spend data in the selected time range.</div>
  {% else %}
  <div class="body">
    {% for row in rows %}{% if row["_fork"].value == "fork1" %}
    {% assign spend = row["Total Spend ($)"].value | default: 0 %}
    {% assign pct = spend | divided_by: 5.0 | times: 100 %}
    {% assign pctShow = pct | round: 1 %}
    {% assign pctArc = pct %}{% if pctArc > 100 %}{% assign pctArc = 100 %}{% endif %}
    {% assign off = 100 | minus: pctArc %}
    {% assign cents = spend | times: 100 | round %}
    {% assign dollars = cents | divided_by: 100 | floor %}
    {% assign rem = cents | modulo: 100 %}
    {% if spend >= 5 %}{% assign lvl = "bad" %}{% assign lvlc = "lvl-red" %}{% elsif spend >= 1 %}{% assign lvl = "warn" %}{% assign lvlc = "" %}{% else %}{% assign lvl = "ok" %}{% assign lvlc = "" %}{% endif %}
    <div class="ringwrap {{ lvlc }}">
      <svg width="180" height="180" viewBox="0 0 180 180">
        <circle class="track" cx="90" cy="90" r="74" fill="none" stroke-width="14"/>
        <circle class="glow {{ lvl }}" cx="90" cy="90" r="74" fill="none" stroke-width="18" pathLength="100" stroke-dasharray="100 100" style="stroke-dashoffset: {{ off }};"/>
        <circle class="arc {{ lvl }}" cx="90" cy="90" r="74" fill="none" stroke-width="14" stroke-linecap="round" pathLength="100" style="--off: {{ off }};"/>
      </svg>
      <div class="center">
        <div class="big {{ lvl }}-t">${{ dollars }}.{% if rem < 10 %}0{% endif %}{{ rem }}</div>
        <div class="lbl">{{ pctShow }}% of $5 budget</div>
      </div>
    </div>
    <div class="side">
      <div class="stats">
        <div class="stat">
          <div class="lbl">Avg cost / request</div>
          <div class="v">${{ row["Average Cost per Request"].value | round: 5 }}</div>
        </div>
        <div class="stat">
          <div class="lbl">Total requests</div>
          {% assign req = row["Total Requests"].value | default: 0 %}
          <div class="v">{% if req >= 1000000 %}{{ req | divided_by: 1000000.0 | round: 2 }}M{% elsif req >= 1000 %}{{ req | divided_by: 1000.0 | round: 1 }}K{% else %}{{ req }}{% endif %}</div>
        </div>
      </div>
      <div class="models">
        <div class="lbl">Top models by spend</div>
        {% assign n = 0 %}
        {% for m in rows %}{% if m["_fork"].value == "fork2" and n < 3 %}
        <div class="m-row">
          <div class="m-top"><span class="m-name">{{ m["Model"].value }}</span><span class="m-val">${{ m["Spend"].value | default: 0 | round: 3 }}</span></div>
          <div class="bar-bg"><div class="bar c{{ n }}" style="width: {{ m["Spend"].pct | default: 0 }}%;"></div></div>
        </div>
        {% assign n = n | plus: 1 %}
        {% endif %}{% endfor %}
        {% if n == 0 %}<div class="lbl">No model breakdown available.</div>{% endif %}
      </div>
    </div>
    {% endif %}{% endfor %}
  </div>
  {% endif %}
</div>"},"panelIndex":"spend-budget","gridData":{"w":16,"x":32,"h":24,"y":0,"i":"spend-budget","sectionId":"live-activity"}}]

