  body { margin: 0; padding: var(--cc-space-l); box-sizing: border-box; font-family: var(--cc-font-family); }
  *, *::before, *::after { box-sizing: border-box; }
  .grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: var(--cc-space-m); }
  .card { position: relative; background: var(--cc-color-surface); border-radius: var(--cc-radius); padding: var(--cc-space-m); box-shadow: 0 1px 3px color-mix(in srgb, var(--cc-color-text) 10%, transparent), 0 1px 2px color-mix(in srgb, var(--cc-color-text) 6%, transparent); display: flex; flex-direction: column; gap: var(--cc-space-xs); min-width: 0; overflow: hidden; }
