  .card.s-critical { background: color-mix(in srgb, var(--cc-color-danger) 8%, var(--cc-color-surface)); }
  .top { display: flex; align-items: center; justify-content: space-between; gap: var(--cc-space-s); }
  .icon { width: 24px; height: 24px; display: flex; align-items: center; justify-content: center; color: var(--status-color); }
  .icon svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
  .badge { display: inline-flex; align-items: center; gap: var(--cc-space-xs); font-size: 0.75rem; font-weight: 600; letter-spacing: 0.04em; padding: 2px var(--cc-space-s); border-radius: var(--cc-radius-s); color: var(--status-color); background: color-mix(in srgb, var(--status-color) 15%, transparent); white-space: nowrap; }
  .dot { position: relative; width: 6px; height: 6px; border-radius: 50%; background: var(--status-color); }
  .dot::after { content: ""; position: absolute; inset: 0; border-radius: 50%; background: var(--status-color); animation: pulse var(--cc-motion-slow) var(--cc-ease) 4; }
  @keyframes pulse { 0% { transform: scale(1); opacity: 0.7; } 100% { transform: scale(2.6); opacity: 0; } }
  .label { font-size: 0.75rem; color: color-mix(in srgb, var(--cc-color-text) 70%, transparent); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .value { font-size: 1.5rem; font-weight: 600; line-height: 1.2; }
  .value .unit { font-size: 0.875rem; font-weight: 400; color: color-mix(in srgb, var(--cc-color-text) 60%, transparent); }
  .hint { font-size: 0.75rem; color: color-mix(in srgb, var(--cc-color-text) 55%, transparent); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  .bar { height: 4px; border-radius: var(--cc-radius-s); background: color-mix(in srgb, var(--cc-color-text) 10%, transparent); overflow: hidden; }
  .bar > div { height: 100%; background: var(--status-color); border-radius: var(--cc-radius-s); }
  .s-healthy { --status-color: var(--cc-color-accent); }
  .s-warning { --status-color: var(--cc-color-warning); }
  .s-critical { --status-color: var(--cc-color-danger); }
  .s-info { --status-color: var(--cc-color-primary); }
  .s-nodata { --status-color: color-mix(in srgb, var(--cc-color-text) 45%, transparent); }
  .empty { font-size: 0.875rem; color: color-mix(in srgb, var(--cc-color-text) 60%, transparent); padding: var(--cc-space-l); text-align: center; }
</style>

