{% assign r = rows[0] %}
<div class="grid">

  {% assign v = r["answer_rate"].value %}
  {% if v == nil or v == "" %}{% assign s = "nodata" %}{% elsif v >= 95 %}{% assign s = "healthy" %}{% elsif v >= 80 %}{% assign s = "warning" %}{% else %}{% assign s = "critical" %}{% endif %}
