    </div>
    <div class="label">Answer rate</div>
    <div class="value">{% if s == "nodata" %}—{% else %}{{ v | round: 1 }}<span class="unit">%</span>{% endif %}</div>
    <div class="hint">Healthy ≥ 95% · Critical &lt; 80%</div>
  </div>

  {% assign v = r["avg_faithfulness"].value %}
  {% if v == nil or v == "" %}{% assign s = "nodata" %}{% elsif v >= 4 %}{% assign s = "healthy" %}{% elsif v >= 3 %}{% assign s = "warning" %}{% else %}{% assign s = "critical" %}{% endif %}
